package ads.poo;

import java.util.ArrayList;

public class App {
    

    public static void main(String[] args) {

        Disciplina dis = new Disciplina("poo", 
            new DiaDaSemana[]{DiaDaSemana.SEGUNDA, DiaDaSemana.TERCA}
        );


        System.out.println(dis);

        ArrayList<Disciplina> disciplinas = new ArrayList<Disciplina>();

        disciplinas.add(new Disciplina("poo", new DiaDaSemana[]{DiaDaSemana.TERCA, DiaDaSemana.QUARTA} ));
        disciplinas.add(new Disciplina("front", new DiaDaSemana[]{DiaDaSemana.TERCA, DiaDaSemana.SEXTA} ));
        disciplinas.add(new Disciplina("est", new DiaDaSemana[]{DiaDaSemana.QUARTA, DiaDaSemana.SEXTA} ));


        for (Disciplina disciplina : disciplinas) {

            for ( DiaDaSemana dia : disciplina.getDiasComAula()) {

                if(dia == DiaDaSemana.TERCA){
                    System.out.println(disciplina.getSigla());
                    
                }
                
            }
            
        }
    }
}
